from scipy import ndimage
import numpy as np
from collections import defaultdict

def comps(g, bg):
    g=np.array(g); mask=g!=bg
    lab,n=ndimage.label(mask, structure=np.ones((3,3)))
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sub=(lab[ys.min():ys.max()+1, xs.min():xs.max()+1]==i)
        out.append(dict(col=int(g[ys[0],xs[0]]), pat=tuple(map(tuple,sub)), n=len(ys), pos=(int(ys.min()),int(xs.min()))))
    return out

def variants(pat):
    a=np.array(pat)
    out=set()
    for k in range(4):
        r=np.rot90(a,k)
        out.add(tuple(map(tuple,r)))
        out.add(tuple(map(tuple,np.fliplr(r))))
    return out

def report(demo_in, bg, changed_pos, label):
    cs=comps(demo_in,bg)
    tgt=[c for c in cs if c['pos']==changed_pos][0]
    print("=== ",label,"changed:",tgt['col'],"-> size",tgt['n'])
    for c in cs:
        if c is tgt: continue
        match=[]
        if c['pat']==tgt['pat']: match.append("SAME")
        if c['pat'] in variants(tgt['pat']): match.append("ROT/FLIP")
        # scale: downsample c by integer factor and compare
        a=np.array(c['pat'])
        for f in range(2,6):
            if a.shape[0]%f==0 and a.shape[1]%f==0:
                b=a[::f,::f]
                if tuple(map(tuple,b))==tgt['pat'] or tuple(map(tuple,b)) in variants(tgt['pat']): match.append(f"SCALE1/{f}")
        # tgt scaled up equals c?
        t=np.array(tgt['pat'])
        for f in range(2,6):
            if t.shape[0]*f==a.shape[0] and t.shape[1]*f==a.shape[1]:
                b=a[::f,::f]
                if np.array_equal(b,t): match.append(f"TGT-SCALEx{f}")
        if match: print("  candidate:",c['col'],"size",c['n'],"pos",c['pos'],match)

