def report2(g,bg,cell,label):
    g=np.array(g); mask=g!=bg
    lab,n=ndimage.label(mask,structure=np.ones((3,3)))
    L=lab[cell]
    ys,xs=np.where(lab==L)
    sub=(lab[ys.min():ys.max()+1,xs.min():xs.max()+1]==L)
    tgt=dict(col=int(g[ys[0],xs[0]]),pat=tuple(map(tuple,sub)),n=len(ys),pos=(int(ys.min()),int(xs.min())))
    print("===",label,"changed color",tgt['col'],"size",tgt['n'],"at",tgt['pos'])
    for row in tgt['pat']: print(''.join('#' if v else '.' for v in row))
    cs=[]
    for i in range(1,n+1):
        if i==L: continue
        ys,xs=np.where(lab==i)
        s=(lab[ys.min():ys.max()+1,xs.min():xs.max()+1]==i)
        cs.append(dict(col=int(g[ys[0],xs[0]]),pat=tuple(map(tuple,s)),n=len(ys),pos=(int(ys.min()),int(xs.min()))))
    for c in cs:
        m=[]
        if c['pat']==tgt['pat']: m.append('SAME')
        if c['pat'] in variants(tgt['pat']): m.append('ROTF')
        a=np.array(c['pat']); t=np.array(tgt['pat'])
        for f in range(2,7):
            if a.shape[0]%f==0 and a.shape[1]%f==0:
                b=a[::f,::f]
                if tuple(map(tuple,b)) in variants(tgt['pat']) or tuple(map(tuple,b))==tgt['pat']: m.append(f"down{f}")
            if t.shape[0]*f==a.shape[0] and t.shape[1]*f==a.shape[1]:
                b=a[::f,::f]
                if np.array_equal(b,t): m.append(f"tgtX{f}")
        if m: print("  cand:",c['col'],c['n'],c['pos'],m)
